def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    # Left frame is the contiguous background-colored run in the top row.
    left_w = 0
    while left_w < w and grid[0][left_w] == bg:
        left_w += 1
    inner_w = left_w - 2
    # Full background rows delimit the stacked frames.
    sep = [r for r in range(h) if all(grid[r][c] == bg for c in range(left_w))]
    panels = [(a, b) for a, b in zip(sep, sep[1:]) if b > a]
    out = [row[:left_w] for row in grid]
    right_x = left_w + 1
    for top, bottom in panels:
        inner_h = bottom - top - 1
        if inner_h <= 0 or inner_w <= 0:
            continue
        target = [[grid[r][c] != bg for c in range(1, left_w-1)] for r in range(top+1, bottom)]
        match = None
        colors = sorted({grid[r][c] for r in range(top+1, bottom)
                         for c in range(right_x, min(w, right_x+inner_w)) if grid[r][c] != 0 and grid[r][c] != bg})
        for color in colors:
            mask = [[grid[r][right_x+j] == color for j in range(inner_w)]
                    for r in range(top+1, bottom)]
            if mask == target:
                match = color
                break
        if match is not None:
            for i, r in enumerate(range(top+1, bottom)):
                for j, c in enumerate(range(1, left_w-1)):
                    if target[i][j]:
                        out[r][c] = match
    return out
