def transform(grid):
    h, w = len(grid), len(grid[0])
    frame = grid[0][0]
    # Find the framed left canvas width from the uniform top edge.
    left_w = 0
    while left_w < w and grid[0][left_w] == frame:
        left_w += 1
    # Horizontal frame rows delimit the template cells.
    separators = [r for r in range(h) if all(grid[r][c] == frame for c in range(left_w))]
    panels = [(a, b) for a, b in zip(separators, separators[1:]) if b - a >= 2]
    # Match each panel's zero-cell mask against each colored source object's mask.
    right_start = left_w + 1
    objects = []
    colors = {grid[r][c] for r in range(h) for c in range(right_start, w)
              if grid[r][c] not in (0, frame)}
    for color in colors:
        cells = {(r, c) for r in range(h) for c in range(right_start, w) if grid[r][c] == color}
        while cells:
            seed = next(iter(cells))
            comp = {seed}
            stack = [seed]
            cells.remove(seed)
            while stack:
                r, c = stack.pop()
                for p in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                    if p in cells:
                        cells.remove(p); comp.add(p); stack.append(p)
            minr=min(r for r,c in comp); maxr=max(r for r,c in comp)
            minc=min(c for r,c in comp); maxc=max(c for r,c in comp)
            mask=tuple(tuple((r,c) in comp for c in range(minc,maxc+1)) for r in range(minr,maxr+1))
            objects.append((color,mask))
    out = [row[:left_w] for row in grid]
    for top, bottom in panels:
        # Interior excludes the top/bottom frame rows and the two side columns.
        mask = tuple(tuple(grid[r][c] == 0 for c in range(1,left_w-1)) for r in range(top+1,bottom))
        for color, shape in objects:
            if shape == mask:
                for i, r in enumerate(range(top+1,bottom)):
                    for j, c in enumerate(range(1,left_w-1)):
                        if mask[i][j]: out[r][c] = color
                break
    return out
